import fnmatch
import os
import subprocess
import typing

from apscheduler.events import (
    EVENT_JOB_ERROR,
    EVENT_JOB_EXECUTED,
    EVENT_JOB_SUBMITTED,
    JobEvent,
)
from apscheduler.schedulers.blocking import BlockingScheduler
from apscheduler.schedulers.asyncio import AsyncIOScheduler
from apscheduler.util import undefined


class OlAsyncIOScheduler(AsyncIOScheduler):
    def __init__(self):
        super().__init__({'apscheduler.timezone': 'UTC'})
        self.add_listener(
            job_listener, EVENT_JOB_EXECUTED | EVENT_JOB_ERROR | EVENT_JOB_SUBMITTED
        )

    @typing.override
    def add_job(
        self,
        func,
        trigger=None,
        args=None,
        kwargs=None,
        id=None,
        name=None,
        misfire_grace_time=undefined,
        coalesce=undefined,
        max_instances=undefined,
        next_run_time=undefined,
        jobstore="default",
        executor="default",
        replace_existing=False,
        **trigger_args,
    ):
        return super().add_job(
            func,
            trigger,
            args,
            kwargs,
            # Override to avoid duplicating the function name everywhere
            id or func.__name__,
            name,
            misfire_grace_time,
            coalesce,
            max_instances,
            next_run_time,
            jobstore,
            executor,
            replace_existing,
            **trigger_args,
        )


class OlBlockingScheduler(BlockingScheduler):
    """Compatibility scheduler for existing synchronous monitoring users."""

    def __init__(self):
        super().__init__({'apscheduler.timezone': 'UTC'})
        self.add_listener(
            job_listener, EVENT_JOB_EXECUTED | EVENT_JOB_ERROR | EVENT_JOB_SUBMITTED
        )

    @typing.override
    def add_job(self, func, trigger=None, **kwargs):
        kwargs.setdefault('id', func.__name__)
        return super().add_job(func, trigger, **kwargs)


def job_listener(event: JobEvent):
    if event.code == EVENT_JOB_SUBMITTED:
        print(f"Job {event.job_id} has started.", flush=True)
    elif event.code == EVENT_JOB_EXECUTED:
        print(f"Job {event.job_id} completed successfully.", flush=True)
    elif event.code == EVENT_JOB_ERROR:
        print(f"Job {event.job_id} failed.", flush=True)


def bash_run(cmd: str, sources: list[str] | None = None, capture_output=False):
    if not sources:
        sources = []

    source_paths = [
        (
            os.path.join("scripts", "monitoring", source)
            if not os.path.isabs(source)
            else source
        )
        for source in sources
    ]
    bash_command = "\n".join(
        (
            'set -e',
            *(f'source "{path}"' for path in source_paths),
            cmd,
        )
    )

    return subprocess.run(
        [
            "bash",
            "-c",
            bash_command,
        ],
        check=True,
        # Mainly for testing:
        capture_output=capture_output,
        text=capture_output if capture_output else None,
    )


def get_service_ip(image_name: str) -> str:
    """Return the IP of a running Docker container."""
    container = image_name.split('/')[-1]
    result = subprocess.run(
        ['docker', 'inspect', '--format',
         '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}', container],
        check=True, capture_output=True, text=True,
    )
    return result.stdout.strip()


def limit_server(allowed_hosts: list[str], scheduler: AsyncIOScheduler | BlockingScheduler):
    """
    Remove a decorated job when the current host is outside the allowlist.

    :param allowed_hosts: Exact hostnames or prefixes ending in ``*``.
    """

    def decorator(func):
        hostname = os.environ.get("HOSTNAME", "")
        short_name = hostname.split('.', 1)[0]
        if not any(
            fnmatch.fnmatchcase(name, pattern)
            for pattern in allowed_hosts
            for name in (hostname, short_name)
        ):
            scheduler.remove_job(func.__name__)
        return func

    return decorator

